type ContentType={id:string;label:string;icon:string;base_kind:Kind;active:boolean;ui_labels?:CardLabels|null};
type Kind = "artist"|"book"|"movie"|"series"|"game"|"place"|"director"|"actor"|"writer"|"comedian"|"theatre_artist"|"athlete"|"club"|"sport"|"hobby"|"activity";
type SeedType = { id:string; name:string; slug:string; icon:string };
type Internal = { catalogItemId:string; canonicalTargetId:string|null; title:string; subtitle:string|null; coverUrl:string|null; seedTypeIcon:string|null; itemKind?:string|null };
type External = { provider:string; externalId:string; title:string; subtitle:string|null; creatorName:string|null; coverUrl:string|null; sourceUrl:string|null; metadata:Record<string,unknown> };
type Selected = { catalogItemId:string; canonicalTargetId:string|null; title:string; subtitle:string|null; coverUrl:string|null; itemKind?:Kind;contentTypeId?:string;aggregateWanting?:number;aggregateDone?:number;aggregateActive?:number; initialView?:"overview"|"want"|"done"|"events"|"want_form"|"done_form"|"event_form" };
type Catalogue = { cover_position_y?:number; content_type_id?:string|null;active_event_count?:number;completed_event_count?:number;expired_event_count?:number;cancelled_event_count?:number; canonical_target_id:string; catalog_item_id?:string|null; title:string; subtitle:string|null; catalog_cover_url:string|null; cover_url:string|null; item_kind?:string|null; seed_type_slug:string|null; seed_type_name?:string|null; canonical_kind?:string|null; activity_id?:string|null; own_seed_id?:string|null; own_common_intent_id?:string|null; own_seed_status?:string|null; intent_people_count:number|string|null; experience_people_count:number|string|null; social_intent_count?:number|string|null };

const KINDS:Array<{id:Kind;label:string;icon:string;placeholder:string}> = [
  {id:"movie",label:"Film",icon:"🎬",placeholder:"Film ara"},{id:"series",label:"Dizi",icon:"📺",placeholder:"Dizi ara"},
  {id:"book",label:"Kitap",icon:"📚",placeholder:"Kitap veya yazar ara"},{id:"artist",label:"Sanatçı",icon:"🎵",placeholder:"Sanatçı veya müzik ara"},
  {id:"game",label:"Oyun",icon:"🎮",placeholder:"Oyun ara"},{id:"place",label:"Yer",icon:"📍",placeholder:"Şehir, ülke, müze veya yer ara"},
  {id:"club",label:"Spor kulübü",icon:"⚽",placeholder:"Kulüp veya takım ara"},{id:"sport",label:"Spor",icon:"🏃",placeholder:"Spor dalı ara"},
  {id:"director",label:"Yönetmen",icon:"🎥",placeholder:"Yönetmen ara"},{id:"actor",label:"Oyuncu",icon:"🎭",placeholder:"Oyuncu ara"},
  {id:"writer",label:"Yazar",icon:"✍️",placeholder:"Yazar ara"},{id:"comedian",label:"Komedyen",icon:"🎙️",placeholder:"Komedyen ara"},
  {id:"theatre_artist",label:"Tiyatrocu",icon:"🎭",placeholder:"Tiyatro sanatçısı ara"},{id:"athlete",label:"Sporcu",icon:"🏅",placeholder:"Sporcu ara"},
  {id:"hobby",label:"Hobi",icon:"🧩",placeholder:"Hobi ara"},{id:"activity",label:"Aktivite",icon:"✨",placeholder:"Aktivite ara"},
];

function language(kind:Kind){
  if(kind==="movie"||kind==="series"||kind==="director"||kind==="actor")return{want:"İzlemek istiyorum",done:"İzledim",question:`Hangi ${kind==="series"?"diziyi":"filmi"} arıyorsun?`,seed:/watch|izle/,categories:["Kültür ve Etkinlikler"]};
  if(kind==="book"||kind==="writer")return{want:"Okumak istiyorum",done:"Okudum",question:"Ne okumak istiyorsun?",seed:/read|oku/,categories:["Öğrenme","Kültür ve Etkinlikler"]};
  if(kind==="artist")return{want:"Dinlemek istiyorum",done:"Dinledim",question:"Ne dinlemek istiyorsun?",seed:/listen|dinle/,categories:["Kültür ve Etkinlikler"]};
  if(kind==="game")return{want:"Oynamak istiyorum",done:"Oynadım",question:"Ne oynamak istiyorsun?",seed:/play|oyna/,categories:["Oyun ve Eğlence"]};
  if(kind==="place"||kind==="club")return{want:"Gitmek istiyorum",done:"Gittim",question:"Nereye gitmek istiyorsun?",seed:/visit|git|ziyaret/,categories:["Seyahat","Açık Hava ve Doğa"]};
  return{want:"Yapmak istiyorum",done:"Yaptım",question:"Ne yapmak istiyorsun?",seed:/try|do|make|dene|yap|learn|öğren/,categories:["Yaratıcı Aktiviteler","Spor","İş ve Üretim"]};
}
function norm(value:string){return value.toLocaleLowerCase("tr-TR").trim()}
function cardKind(item:Catalogue):Kind{
  const stored=norm(item.item_kind||"");
  const seed=norm(`${item.seed_type_slug||""} ${item.seed_type_name||""}`);
  if(stored==="activity"&&item.canonical_kind==="personal"&&/\bvisit\b/.test(seed))return"place";
  if(stored==="video")return"series";
  const explicit=KINDS.find(type=>type.id===stored);
  if(explicit)return explicit.id;
  if(/sport activity|sport-do|spor dalı/.test(seed))return"sport";
  if(/watch|izle/.test(seed))return"movie";
  if(/read|oku/.test(seed))return"book";
  if(/listen|dinle/.test(seed))return"artist";
  if(/\bvisit\b|ziyaret/.test(seed))return"place";
  if(/play|oyna/.test(seed))return"game";
  return"activity";
}
function matches(item:Catalogue,kind:Kind){return (item.content_type_id||cardKind(item))===kind}
function showsCreator(typeId:string|undefined|null,baseKind:Kind){
  const id=norm(typeId||"");
  return !/(festival|concert|konser)/.test(id)&&["artist","book","movie","series","game","director","actor","writer"].includes(baseKind);
}
function eventCount(item:Catalogue){return Number(item.active_event_count??item.social_intent_count??0)}
function compareCards(a:Catalogue,b:Catalogue){return Number(b.intent_people_count||0)-Number(a.intent_people_count||0)||eventCount(b)-eventCount(a)||commonIntentTitle(a.title).localeCompare(commonIntentTitle(b.title),"tr")}

const CARDS_PER_PAGE=20;
function paginate<T>(items:T[],page:number){const pages=Math.max(1,Math.ceil(items.length/CARDS_PER_PAGE));const currentPage=Math.min(Math.max(1,page),pages);return {items:items.slice((currentPage-1)*CARDS_PER_PAGE,currentPage*CARDS_PER_PAGE),page:currentPage,pages}}
function CardPagination({total,page,onChange}:{total:number;page:number;onChange:(page:number)=>void}){const pages=Math.ceil(total/CARDS_PER_PAGE);if(pages<=1)return null;const visible=Array.from(new Set([1,...Array.from({length:5},(_,i)=>page-2+i).filter(n=>n>1&&n<pages),pages]));return <nav aria-label="Kütüphane sayfaları" className="mt-6 flex flex-wrap items-center justify-center gap-2"><p className="w-full text-center text-sm text-slate-500">{(page-1)*CARDS_PER_PAGE+1}–{Math.min(page*CARDS_PER_PAGE,total)} / {total} kayıt · Sayfa {page} / {pages}</p><button type="button" disabled={page===1} onClick={()=>onChange(page-1)} className="rounded-xl border bg-white px-4 py-2 text-sm font-bold disabled:opacity-40">← Önceki</button>{visible.map((n,i)=><span key={n} className="flex items-center gap-2">{i>0&&n-visible[i-1]>1&&<span aria-hidden="true" className="px-1 text-slate-500">…</span>}<button type="button" aria-label={`Sayfa ${n}`} aria-current={page===n?"page":undefined} onClick={()=>onChange(n)} className={`h-10 min-w-10 rounded-xl border px-3 font-bold ${page===n?"border-emerald-600 bg-emerald-600 text-white":"bg-white hover:bg-emerald-50"}`}>{n}</button></span>)}<button type="button" disabled={page===pages} onClick={()=>onChange(page+1)} className="rounded-xl border bg-white px-4 py-2 text-sm font-bold disabled:opacity-40">Sonraki →</button></nav>}

function TopicPreviewCard({item,isAdmin,onOpen,onEdit,contentTypes,club,teamCount=0,place,nearby=[],onOpenPlace,onCity}:{club?:ClubCard;teamCount?:number;place?:Place;nearby?:Place[];onOpenPlace?:(p:Place)=>void;onCity?:(id:string)=>void;contentTypes:ContentType[];item:Catalogue;isAdmin:boolean;onOpen:(view:Selected["initialView"])=>void;onEdit:()=>void}){
  const itemKind=contentTypes.find(type=>type.id===(item.content_type_id||cardKind(item)))?.base_kind||cardKind(item);
  const displayTitle=club?.displayName||commonIntentTitle(item.title);
  const words=cardWords(itemKind,contentTypes.find(type=>type.id===(item.content_type_id||cardKind(item)))?.ui_labels);
  const imageUrl=item.catalog_cover_url||item.cover_url;
  const clubLogoUrl=itemKind==="club"?(club?.logoUrl||imageUrl):null;
  const completed=item.own_seed_status==="completed";const canWant=true;
  const wantingAlready=Boolean(item.own_common_intent_id||(!completed&&item.own_seed_id));
  const metrics=[{label:words.wanting,count:Number(item.intent_people_count||0),view:"want" as const,tone:"border-emerald-100 bg-emerald-50 text-emerald-900"},{label:words.doers,count:Number(item.experience_people_count||0),view:"done" as const,tone:"border-purple-100 bg-purple-50 text-purple-900"},{label:"Aktif etkinlikler",count:eventCount(item),view:"events" as const,tone:"border-violet-100 bg-violet-50 text-violet-900"}];
  return <article style={cardFrameStyle(club?.cardStyle)} className="flex min-w-0 flex-col overflow-hidden rounded-[26px] border border-slate-200 bg-white shadow-[0_8px_28px_-20px_rgba(15,23,42,.45)] transition-shadow hover:shadow-[0_18px_38px_-22px_rgba(15,23,42,.45)]">
    <button type="button" onClick={()=>onOpen("overview")} className="group block w-full text-left"><div style={itemKind==="club"?{backgroundColor:club?.cardStyle?.background||"#ffffff"}:undefined} className={`uin-card-cover relative overflow-hidden ${itemKind==="club"?"":"bg-slate-100"}`}>{itemKind==="club"?(clubLogoUrl?<img src={clubLogoUrl} alt={`${displayTitle} logosu`} className="absolute left-1/2 top-1/2 max-h-[68%] max-w-[56%] -translate-x-1/2 -translate-y-1/2 object-contain transition-transform duration-300 group-hover:scale-[1.04]"/>:<span className="grid h-full place-items-center text-5xl">{KINDS.find(type=>type.id===itemKind)?.icon||"▦"}</span>):imageUrl?<img src={imageUrl} style={{objectPosition:`50% ${item.cover_position_y??50}%`}} alt="" className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-[1.04]"/>:<span className="grid h-full place-items-center text-5xl">{KINDS.find(type=>type.id===itemKind)?.icon||"▦"}</span>}{teamCount>0&&<span className="absolute bottom-3 left-3 rounded-full bg-white/95 px-3 py-2 text-xs font-black text-emerald-900">{teamCount} takım / branş</span>}{(place?.kind==="Şehir"||place?.kind==="İl")&&nearby.length>0&&<span className="absolute bottom-3 left-3 right-3 w-fit rounded-full bg-white/95 px-3 py-2 text-xs font-black text-emerald-900 shadow-sm">{item.title}’da {nearby.length} öne çıkan yer</span>}</div><div className="min-h-[76px] px-4 pb-2 pt-3"><h3 style={{color:cardTextColour(club?.cardStyle)}} className="line-clamp-2 text-[15px] font-black leading-snug text-slate-950">{displayTitle}</h3>{item.subtitle&&showsCreator(item.content_type_id,itemKind)&&!club?.parent_target_id&&<p className="mt-1 truncate text-xs font-medium text-slate-500">{item.subtitle}</p>}</div></button>
    {club?.parent_target_id&&<p style={{color:cardTextColour(club.cardStyle)}} className="px-4 pb-3 text-xs font-bold text-emerald-800"><span style={{backgroundColor:(club.cardStyle?.primary||"#10b981")+"18",borderColor:club.cardStyle?.primary||"#10b981"}} className="inline-flex rounded-lg border px-2.5 py-1.5">{[club.sport,club.division,club.league,club.season].filter(Boolean).join(" · ")}</span></p>}{place&&<p className="px-4 pb-3 text-xs font-semibold text-slate-500">{[place.kind,place.district,place.city,place.country].filter((v,i,a)=>v&&a.indexOf(v)===i).join(" · ")}</p>}

    <div className="grid grid-cols-3 gap-1.5 px-3 pb-3">{metrics.map(metric=><button key={metric.view} type="button" onClick={()=>onOpen(metric.view)} aria-label={`${metric.label}: ${metric.count}. Listeyi gör`} className={`flex min-h-[64px] flex-col items-center justify-center rounded-xl border px-1.5 text-center transition hover:brightness-[.98] ${metric.tone}`}><span className="text-[10px] font-bold leading-tight">{metric.label}</span><span className="mt-1 text-lg font-black leading-none">{metric.count}</span>{metric.view==="events"&&<span className="mt-1 text-[9px] font-semibold">{item.completed_event_count||0} tamamlandı{Boolean(item.expired_event_count)&&` · ${item.expired_event_count} geçti`}{Boolean(item.cancelled_event_count)&&` · ${item.cancelled_event_count} iptal`}</span>}</button>)}</div>
    <div className="mt-auto border-t border-slate-100 px-3 pb-3 pt-3"><div className={`grid gap-1.5 ${canWant?"grid-cols-3":"grid-cols-2"}`}>{canWant&&<button type="button" onClick={()=>onOpen("want_form")} className="min-h-[60px] rounded-xl bg-emerald-600 px-1.5 py-2 text-center text-[11px] font-black leading-tight text-white transition hover:bg-emerald-700">{wantingAlready?"✓":"＋"}<span className="mt-1 block">{wantingAlready?"İsteğimi düzenle":completed?"Yeniden "+words.want.toLocaleLowerCase("tr-TR"):words.want}</span></button>}<button type="button" onClick={()=>onOpen("done_form")} className="min-h-[60px] rounded-xl bg-purple-600 px-1.5 py-2 text-center text-[11px] font-black leading-tight text-white transition hover:bg-purple-700">{completed?"✓":"＋"}<span className="mt-1 block">{completed?"Deneyimimi düzenle":words.done}</span></button><button type="button" onClick={()=>onOpen("event_form")} className="min-h-[60px] rounded-xl bg-violet-700 px-1.5 py-2 text-center text-[11px] font-black leading-tight text-white transition hover:bg-violet-800">＋<span className="mt-1 block">{words.event}</span></button></div></div>
    {itemKind==="club"&&<a href={"/clubs/"+item.canonical_target_id} className="border-t px-4 py-3 text-center text-xs font-black text-emerald-700 hover:bg-emerald-50">Kulüp profilini aç ↗</a>}
    {isAdmin&&<div className="border-t border-amber-200 bg-amber-50/70 px-3 py-2.5"><button type="button" onClick={onEdit} className="w-full rounded-xl border border-amber-300 bg-white px-2 py-2 text-xs font-black text-amber-900 hover:bg-amber-100">✎ Düzenle · Türünü değiştir · Sil</button></div>}
  </article>;
}

